  "title": "선천 QT연장증후군 — 재분극 예비력에서 1차 약물 선택까지",
  "objective": "심실 재분극의 생리로 QT 연장이 토르사드 드 푸앵트로 이어지는 기전을 설명하고, 후천 원인을 걸러 선천 QT연장증후군을 진단한 뒤 비선택 베타차단제를 1차로 고르고 QT 연장 약물을 피해야 하는 이유를 판단한다",
  "objectiveKind": "치료",
