  "checks": [
   {
    "q": "심전도 변화가 있는 고칼륨혈증에서 칼슘을 먼저 주는 이유는? 칼슘이 칼륨 수치를 낮추는가?",
    "a": "역치 전위를 올려 막의 흥분성을 곧바로 안정화해 치명적 부정맥을 막기 때문이다. 칼륨 수치는 낮추지 않는다 — 효과가 30~60분이라 이동·제거가 뒤따라야 한다."
   },
   {
    "q": "인슐린+포도당을 준 뒤 칼륨과 혈당을 언제 다시 보나?",
    "a": "칼륨은 최소 1·2·4·6·24시간(반동 확인), 혈당은 12시간까지 여러 번(저혈당). UK KA 권고."
   },
   {
    "q": "칼륨 6.8, 심전도 정상. 칼슘이 첫 처치인가?",
    "a": "UK KA 는 칼슘을 심전도 근거가 있을 때로 한정한다. 수치는 중증이므로 인슐린+포도당으로 이동을 시작하고, 심전도가 둔감하다는 점을 기억해 감시한다(Harrison)."
   }
  ],
  "variants": [
   {
    "id": "cn.neph.hyperkalemia.first-step#v1",
    "context": "같은 목표, 다른 맥락 — 심전도 변화가 없는 중증 고칼륨혈증",
    "stem": "58세 여자가 정기 혈액검사에서 칼륨이 높다는 연락을 받고 왔다. 당뇨병성 콩팥병으로 안지오텐신 수용체 차단제와 스피로놀락톤을 먹고 있다. 증상은 없다. 혈압 134/80 mmHg, 맥박 78회/분. 혈청 칼륨 6.7 mEq/L(용혈 없음), 크레아티닌 2.1 mg/dL, 소변량은 정상이다. 12유도 심전도는 정상 동리듬이며 T파·PR·QRS 변화가 없다. 가장 먼저 할 처치는?",
    "options": [
     "정맥 칼슘글루콘산",
     "정맥 인슐린과 포도당",
     "응급 혈액투석",
     "1주 뒤 재검",
     "생리식염수 대량 투여"
    ],
    "answer": 2,
    "explanation": "칼륨은 중증 범위지만 심전도 변화가 없어 UK KA 기준의 칼슘 적응이 아니다. 중증 고칼륨혈증에는 인슐린+포도당이 권고되고(심전도가 정상이어도 적극 치료 — Harrison), 원인 약물(스피로놀락톤 등)을 멈추고 제거를 이어 간다. 투석은 소변이 나오고 약물 치료를 아직 하지 않은 지금의 첫 처치가 아니며, 1주 뒤 재검은 중증 수치를 방치한다."
   }
  ],
