    "title": "2023 당뇨병 진료지침 — 임신과 당뇨병",
    "kind": "guideline",
    "citation": "대한당뇨병학회. 2023 당뇨병 진료지침(제8판). 임신과 당뇨병 장",
    "checked": "서지만 확인(원문 미대조 — 검토 항목). 학회 홈페이지 주소만 적었고 지침 PDF 의 절·쪽·권고 문구(임신 중 1차 약물 인슐린, 경구제 허가 외)는 대조하지 못했다",
