  "checks": [
   {
    "q": "임신당뇨병에서 생활습관 요법을 시작한 뒤 약물을 더할지 판단하는 시점과 기준은?",
    "a": "영양·운동 요법 1–2주 뒤 자가혈당 기록을 보고, 목표(공복 ≤ 95 · 식후 1시간 ≤ 140 · 2시간 ≤ 120 mg/dL)를 반복해 넘으면 약물을 더한다. 순응이 좋은데도 공복이 높으면 식이 연장으로 해결되지 않는다."
   },
   {
    "q": "임신 중 1차 혈당강하 약물이 인슐린인 이유 둘은?",
    "a": "태반을 유의하게 통과하지 않고, 장기 안전성이 확립돼 있다. 메트포르민·글리부리드는 태반을 통과하고 노출 자녀의 장기 자료가 부족하다."
   },
   {
    "q": "공복 고혈당과 식후 고혈당은 각각 어떤 인슐린으로 맞추는가?",
    "a": "공복 고혈당은 취침 전 NPH(중간형) 또는 지속형 기저 인슐린, 식후 고혈당은 식전 속효·초속효 아날로그."
   },
   {
    "q": "산후에 무엇을, 언제 확인하는가?",
    "a": "분만 직후 인슐린을 중단하고, 산후 4–12주에 75 g 2시간 OGTT(비임신 기준)로 제2형 당뇨병·전당뇨병 이행을 확인한다. 정상이어도 1–3년마다 재선별한다."
   }
  ],
  "variants": [
   {
    "id": "cn.obgyn.gestational-diabetes.insulin-indication#v1",
    "context": "같은 목표, 다른 양상 — 1단계(75 g) 진단 + 식후 고혈당만 반복 + 경구제 요청",
    "stem": "29세 여자(임신 1회 출산 0회)가 임신 28주에 왔다. 임신 26주 75 g 경구 포도당부하검사에서 공복 88 · 1시간 192 · 2시간 160 mg/dL 로 임신당뇨병을 진단받고 2주간 영양 상담대로 탄수화물을 나눠 먹으며 매일 30분 걷고 식단 일지를 쓰고 있다. 최근 1주 자가 혈당은 공복 84–90 mg/dL, 식후 1시간 152–168 mg/dL 로 7일 중 6일 식후 목표를 넘었다. 체중은 2주간 0.5 kg 늘었고 소변 케톤은 음성이다. 태아 추정 체중은 65백분위다. 환자는 주사가 무서워 먹는 약을 원한다고 한다. 가장 적절한 처치는?",
    "options": [
     "식단을 재조정하고 2주 더 관찰한다",
     "메트포르민을 시작한다",
     "식전 속효 인슐린을 시작한다",
     "취침 전 NPH 인슐린을 시작한다",
     "글리부리드를 시작한다"
    ],
    "answer": 3,
    "explanation": "순응이 좋은 2주 요법 뒤에도 식후 1시간 혈당이 목표(≤ 140)를 반복해 넘어 약물 시작 기준을 충족했다. 임신 중 1차 약물은 인슐린이며, 공복은 목표 안이고 식후만 높으므로 식전 속효·초속효 인슐린으로 맞춘다(취침 전 NPH 는 공복 고혈당의 처방). 주사에 대한 두려움은 교육·상담으로 먼저 다루고, 메트포르민은 상담 뒤에도 거부하거나 투여가 불가능할 때의 대안이며 글리부리드는 권하지 않는다. 식단 재조정 2주 연장은 이미 순응이 좋은 상태에서 초과가 반복되므로 지연이다."
   }
  ],
